// Space Grotesk and IBM Plex Mono, the two faces the site uses, carried
// inline so the card renderer never depends on a file path or a font CDN.
// Latin subsets from @fontsource, SIL Open Font License.

const sg700 = '';
const sg500 = '';
const mono400 = '';
const mono500 = '';

const dec = s => Buffer.from(s, 'base64');
const FONTS = [
  { name: 'Grotesk', data: dec(sg700), weight: 700, style: 'normal' },
  { name: 'Grotesk', data: dec(sg500), weight: 500, style: 'normal' },
  { name: 'Mono',    data: dec(mono500), weight: 500, style: 'normal' },
  { name: 'Mono',    data: dec(mono400), weight: 400, style: 'normal' },
];

module.exports = { FONTS };
